-- Aquagram — 0061: 26 yeni tür (amfibiler, sıra dışı balıklar, kalem/balta balıkları, vatoz, gar) + pençeli kurbağa varyeteleri
-- Görsel numaraları: 791–816 türler, 817 = Xenopus laevis 'Albino' varyetesi (scripts/gorsel-numaralari.json).
on conflict (slug) do nothing;

select s.id, f.name, 'varyete', f.origin, f.note, f.aliases, f.pos, 'published' from public.species s cross join (values
  (0, 'Wild Type', 'Doğal renk', 'Zeytin yeşili-kahverengi, benekli doğal renk.', array['Yabani tip','Normal']::text[]),
  (1, 'Albino', 'Akvaryum üretimi', 'Beyaz-pembe gövde ve kırmızı gözler; hobide en sık bulunan formdur.', array['Albino pençeli kurbağa','Beyaz kurbağa']::text[])
) as f(pos, name, origin, note, aliases)
where s.slug = 'xenopus-laevis' and not exists (select 1 from public.species_forms x where x.species_id = s.id and x.name = f.name);
