insert into public.species (slug, name, latin, category_id, kind, difficulty, temperament, description, facts, keywords, is_rare, care_notice, range_areas, status)
values
('hymenochirus-boettgeri','Cüce Afrika Kurbağası','Hymenochirus boettgeri','diger-baliklar','fish','Orta','Barışçıl, grup hâlinde','Tamamen suda yaşayan, 3–4 cm''lik küçük bir kurbağa. Nefes almak için yüzeye çıkar; görmesi zayıf olduğundan yemini koku ile bulur. Küçük ve sakin balıklarla birlikte tutulabilir ama yem yarışını kaybetmemesi için ayrıca beslenmelidir.','[["Yetişkin boy", "3–4 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "6.5–7.8"], ["Min. akvaryum", "40 L (3–4 birey)"], ["Huy", "Barışçıl, grup hâlinde"], ["Beslenme", "Etçil: kan kurdu, artemia, batan granül"], ["Üreme", "Yumurtlayan (yüzeye yumurta bırakır)"], ["Köken", "Orta Afrika, Kongo havzası"], ["Ömür", "5–10 yıl"], ["Özellikler", "Tamamen sucul, yüzeyden hava solur"]]'::jsonb,array['cüce afrika kurbağası','cüce kurbağa','akvaryum kurbağası','african dwarf frog','adf','hymenochirus','hymenochirus boettgeri','kurbağa']::text[],false,'Albino pençeli kurbağa (Xenopus) ile sık karıştırılır: cüce kurbağanın ön ayakları perdelidir, Xenopus''un ise ön ayakları perdesizdir ve çok büyür; onu yiyebilir. Yüzeye rahat çıkabilmesi için su seviyesi 30 cm''yi geçmemeli; kapak şart.','[{"r": 500, "lat": 0.5, "lng": 18.5, "label": "Kongo Havzası"}]'::jsonb,'published'),
('xenopus-laevis','Pençeli Kurbağa (Afrika Pençeli Kurbağası)','Xenopus laevis','diger-baliklar','fish','Kolay','Ağzına sığan her canlıyı yer','Arka ayaklarında küçük siyah pençeler bulunan, tamamen sucul ve son derece dayanıklı bir kurbağa. Hobide en çok albino formu bulunur. Ağzına sığan her canlıyı yediği için balıklarla ve cüce kurbağalarla tutulmamalıdır.','[["Yetişkin boy", "10–12 cm (dişiler 15 cm''e kadar)"], ["Sıcaklık", "18–24 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "60 L (tek), 100 L (çift)"], ["Huy", "Ağzına sığanı yer; tek tür tank"], ["Beslenme", "Etçil: kurbağa peleti, solucan, karides"], ["Üreme", "Yumurtlayan"], ["Köken", "Güney ve Doğu Afrika"], ["Ömür", "15–20 yıl (30 yıla kadar)"], ["Özellikler", "Tamamen sucul, çok dayanıklı"]]'::jsonb,array['pençeli kurbağa','albino kurbağa','beyaz kurbağa','african clawed frog','clawed frog','xenopus','xenopus laevis','kurbağa']::text[],false,'İstilacı bir türdür; asla doğaya, dereye ya da göle bırakılmamalı. Çok iyi zıplar ve kaçar, kapak şart. Bazı ülkelerde bulundurulması izne tabidir.','[{"r": 900, "lat": -27, "lng": 26, "label": "Güney Afrika"}, {"r": 500, "lat": -2, "lng": 32, "label": "Doğu Afrika göller bölgesi"}]'::jsonb,'published'),
('cynops-orientalis','Ateş Karınlı Semender','Cynops orientalis','diger-baliklar','fish','Orta','Barışçıl','Sırtı koyu, karnı parlak turuncu-kırmızı küçük bir Çin semenderi. Çoğunlukla suda yaşar ama dinlenmek için kara alanı ister; bu yüzden paludaryum ya da yüzen ada kurulmalıdır. Serin suyu sever.','[["Yetişkin boy", "6–10 cm"], ["Sıcaklık", "15–22 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "40 L (2–3 birey), kara alanıyla"], ["Huy", "Barışçıl"], ["Beslenme", "Etçil: kan kurdu, solucan, küçük karides"], ["Üreme", "Yumurtlayan (yumurtaları tek tek yapraklara sarar)"], ["Köken", "Çin (Yangtze havzası)"], ["Ömür", "10–15 yıl (30 yıla kadar)"], ["Özellikler", "Zehirli deri salgısı, serin su"]]'::jsonb,array['ateş karınlı semender','çin semenderi','fire bellied newt','chinese fire belly newt','cynops','cynops orientalis','semender','triton']::text[],false,'Derisi zehirli salgı üretir; elledikten sonra mutlaka el yıka ve başka hayvanlarla aynı tanka koyma. 24 °C üstünde strese girer. Tırmanıp kaçabilir, kapak şart.','[{"r": 500, "lat": 30.5, "lng": 116, "label": "Yangtze havzası (Anhui, Hubei, Jiangsu)"}]'::jsonb,'published'),
('pleurodeles-waltl','İberya Kaburgalı Semenderi','Pleurodeles waltl','diger-baliklar','fish','Kolay','Barışçıl ama obur','Avrupa''nın en büyük semenderlerinden; neredeyse tamamen suda yaşar. Tehlike anında kaburgalarının uçlarını derisinden dışarı iterek kendini korur. Dayanıklı ve obur olduğu için başlangıç seviyesi bir semender sayılır.','[["Yetişkin boy", "15–30 cm"], ["Sıcaklık", "15–22 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "80 L (tek), 120 L (çift)"], ["Huy", "Barışçıl; ağzına sığanı yer"], ["Beslenme", "Etçil: solucan, batan pelet, karides"], ["Üreme", "Yumurtlayan (yüzlerce yumurta)"], ["Köken", "İspanya, Portekiz ve Fas"], ["Ömür", "10–20 yıl"], ["Özellikler", "Kaburga savunması, büyük ölçüde sucul"]]'::jsonb,array['kaburgalı semender','iberya semenderi','spanish ribbed newt','ribbed newt','pleurodeles','pleurodeles waltl','semender','triton']::text[],false,'Balıklarla tutulmaz. Kapak şart.','[{"r": 500, "lat": 39.5, "lng": -5, "label": "İber Yarımadası"}, {"r": 250, "lat": 34, "lng": -6, "label": "Kuzey Fas"}]'::jsonb,'published'),
('typhlonectes-natans','Su Sesilyanı (Kauçuk Yılan)','Typhlonectes natans','diger-baliklar','fish','Orta','Barışçıl, gece aktif','Yılana ya da yılan balığına benzeyen ama aslında bacaksız bir amfibi olan sesilyan. Gözleri körelmiştir; yemini koku ile bulur. Kumda ve kökler arasında saklanır, geceleri aktiftir.','[["Yetişkin boy", "40–55 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl; çok küçük balıkları yiyebilir"], ["Beslenme", "Etçil: solucan, batan pelet, karides"], ["Üreme", "Canlı doğurur"], ["Köken", "Kolombiya ve Venezuela"], ["Ömür", "10+ yıl"], ["Özellikler", "Bacaksız amfibi, kaçma ustası"]]'::jsonb,array['sesilyan','su sesilyanı','kauçuk yılan','rubber eel','caecilian','typhlonectes','typhlonectes natans']::text[],true,'En küçük aralıktan kaçabilir; kapak ve kablo girişleri sıkıca kapatılmalı. Yüzeyden hava alır, su ile kapak arasında boşluk bırakılmalı. Isıtıcı korumalı olmalı.','[{"r": 450, "lat": 7.5, "lng": -72, "label": "Orinoco ve Magdalena havzaları"}]'::jsonb,'published'),
('carinotetraodon-travancoricus','Cüce Balon (Bezelye Balonu)','Carinotetraodon travancoricus','diger-baliklar','fish','Orta','Yüzgeç ısırır; tür içi bölgeci','Dünyanın en küçük balon balıklarından, yalnızca 2,5–3 cm. Tamamen tatlı suda yaşar ve gözlerini bağımsız hareket ettirerek avını izler. Meraklı ve karakterli ama diğer balıkların yüzgeçlerini ısırdığı için tek tür tankta tutulur.','[["Yetişkin boy", "2.5–3.5 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "40 L (tek), birey başına +20 L"], ["Huy", "Agresif; tek tür tank"], ["Beslenme", "Etçil: salyangoz, donuk ve canlı yem"], ["Üreme", "Yumurtlayan (bitkiler arasına)"], ["Köken", "Hindistan (Kerala, Karnataka)"], ["Ömür", "4–5 yıl"], ["Özellikler", "Tatlı su balonu, salyangoz avcısı"]]'::jsonb,array['cüce balon','bezelye balonu','pea puffer','dwarf puffer','balon balığı','carinotetraodon','carinotetraodon travancoricus']::text[],false,'Kuru yemi çoğunlukla yemez; donuk ya da canlı yem ve dişlerini aşındırması için küçük salyangoz gerekir. Karides ve salyangozları yer. Bol bitki ve görüş engeli şart.','[{"r": 250, "lat": 10.5, "lng": 76.3, "label": "Batı Ghatlar, Kerala"}]'::jsonb,'published'),
('colomesus-asellus','Amazon Balonu','Colomesus asellus','diger-baliklar','fish','Orta','Yarı agresif, sosyal','Güney Amerika''nın tatlı sularında yaşayan, sarı-siyah bantlı bir balon balığı. Diğer balonlara göre sosyaldir, küçük gruplar hâlinde tutulabilir ve sürekli hareket hâlindedir.','[["Yetişkin boy", "8–10 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "150 L (grup)"], ["Huy", "Yarı agresif; yüzgeç ısırabilir"], ["Beslenme", "Etçil: salyangoz, midye, donuk yem"], ["Üreme", "Yumurtlayan (akvaryumda nadir)"], ["Köken", "Amazon ve Orinoco havzaları"], ["Ömür", "8–10 yıl"], ["Özellikler", "Tatlı su balonu, sosyal"]]'::jsonb,array['amazon balonu','south american puffer','brazilian puffer','colomesus','colomesus asellus','balon balığı']::text[],false,'Dişleri sürekli uzar; salyangoz ve kabuklu yem şart. Tamamen tatlı su türüdür, tuz eklenmez.','[{"r": 900, "lat": -3, "lng": -60, "label": "Amazon Havzası"}]'::jsonb,'published'),
('parambassis-ranga','Hint Cam Balığı','Parambassis ranga','diger-baliklar','fish','Kolay','Barışçıl, ürkek; sürü','Gövdesi neredeyse tamamen şeffaf; iskeleti ve iç organları dışarıdan görünür. Sürü hâlinde kendini güvende hisseder, tek başına kaldığında saklanır.','[["Yetişkin boy", "6–8 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, 6+ sürü"], ["Beslenme", "Etçil ağırlıklı: kan kurdu, artemia, küçük yem"], ["Üreme", "Yumurta saçıcı (bitkilere)"], ["Köken", "Güney Asya (Hindistan, Bangladeş, Myanmar)"], ["Ömür", "5–7 yıl"], ["Özellikler", "Şeffaf gövde"]]'::jsonb,array['cam balığı','hint cam balığı','glassfish','indian glassfish','parambassis','parambassis ranga','chanda ranga']::text[],false,'Boyalı (enjeksiyonla renklendirilmiş) cam balıkları satılır; bu işlem hayvana zarar verir, bu bireyleri satın alma. Hafif tuzlu suyu da tolere eder.','[{"r": 900, "lat": 23, "lng": 85, "label": "Hindistan alt kıtası"}]'::jsonb,'published'),
('badis-badis','Badis (Bukalemun Balığı)','Badis badis','diger-baliklar','fish','Orta','Barışçıl; erkekler bölgeci','Ruh hâline göre rengini hızla değiştirebildiği için bukalemun balığı olarak bilinir. Küçük, sakin ve karakterli; mağaralarda saklanan erkekler yumurtalara bakar.','[["Yetişkin boy", "6–8 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Erkekler tür içi bölgeci"], ["Beslenme", "Etçil: donuk ve canlı yem"], ["Üreme", "Mağara yumurtlayan, erkek bakar"], ["Köken", "Hindistan, Bangladeş, Nepal"], ["Ömür", "3–5 yıl"], ["Özellikler", "Renk değiştirme"]]'::jsonb,array['badis','blue badis','chameleon fish','bukalemun balığı','badis badis']::text[],false,'Kuru yemi çoğunlukla reddeder. Hızlı ve iri balıklarla yem yarışını kaybeder.','[{"r": 600, "lat": 25, "lng": 87, "label": "Ganj havzası"}]'::jsonb,'published'),
('dario-dario','Kırmızı Badis (Scarlet Badis)','Dario dario','diger-baliklar','fish','Orta','Utangaç; erkekler bölgeci','Yalnızca 2 cm''lik, erkekleri kırmızı-mavi bantlı küçük bir nano balığı. Bol bitkili ve sakin tanklarda en güzel rengini gösterir.','[["Yetişkin boy", "2 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.5–7.8"], ["Min. akvaryum", "30 L"], ["Huy", "Utangaç; erkekler birbirine bölgeci"], ["Beslenme", "Etçil: artemia, canlı ve donuk küçük yem"], ["Üreme", "Yumurtlayan (bitkiler arasına)"], ["Köken", "Hindistan (Batı Bengal, Assam)"], ["Ömür", "2–4 yıl"], ["Özellikler", "Nano, renkli erkekler"]]'::jsonb,array['kırmızı badis','scarlet badis','scarlet gem','dario','dario dario','nano balık']::text[],false,'Kuru yemi nadiren yer. Karides yavrularını avlayabilir.','[{"r": 300, "lat": 26.5, "lng": 89.5, "label": "Brahmaputra havzası (Batı Bengal, Assam)"}]'::jsonb,'published'),
('macrognathus-siamensis','Benekli Hortum Burunlu Yılan Balığı','Macrognathus siamensis','diger-baliklar','fish','Orta','Barışçıl; çok küçük balıkları yer','Uzun, hortuma benzeyen burnu ve sırt yüzgecindeki göz benekleriyle tanınır. Gündüzleri kuma gömülür, akşamları avlanır.','[["Yetişkin boy", "25–30 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl; tür içi kavga edebilir"], ["Beslenme", "Etçil: kan kurdu, solucan, karides"], ["Üreme", "Yumurtlayan"], ["Köken", "Güneydoğu Asya (Mekong, Chao Phraya)"], ["Ömür", "8–15 yıl"], ["Özellikler", "Kuma gömülür"]]'::jsonb,array['peacock eel','hortum burunlu yılan balığı','dikenli yılan balığı','spiny eel','macrognathus','macrognathus siamensis']::text[],false,'İnce kum zemin şart; çakılda derisi yaralanır. Kapak şart, kaçabilir. Neon gibi küçük balıkları yiyebilir.','[{"r": 600, "lat": 15, "lng": 103, "label": "Mekong ve Chao Phraya havzaları"}]'::jsonb,'published'),
('mastacembelus-erythrotaenia','Ateş Yılan Balığı','Mastacembelus erythrotaenia','diger-baliklar','fish','Zor','Yarı agresif; tür içi kavgacı','Koyu gövdesi üzerindeki parlak kırmızı çizgileriyle çok gösterişli, iri bir dikenli yılan balığı. Uzun ömürlüdür ve sahibini tanıyacak kadar etkileşimlidir, ama çok büyük tank ister.','[["Yetişkin boy", "60–100 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "600 L"], ["Huy", "Yarı agresif; ağzına sığanı yer"], ["Beslenme", "Etçil: solucan, karides, balık eti"], ["Üreme", "Yumurtlayan (akvaryumda çok nadir)"], ["Köken", "Güneydoğu Asya (Tayland, Kamboçya, Malezya, Borneo, Sumatra)"], ["Ömür", "10–18 yıl"], ["Özellikler", "Çok büyür, kuma gömülür"]]'::jsonb,array['fire eel','ateş yılan balığı','dikenli yılan balığı','spiny eel','mastacembelus','mastacembelus erythrotaenia']::text[],true,'İnce kum zemin ve sıkı kapak şart. Mağazada 15–20 cm''lik gençler satılır ama 1 metreye yaklaşabilir.','[{"r": 900, "lat": 5, "lng": 105, "label": "Güneydoğu Asya (Mekong''dan Borneo''ya)"}]'::jsonb,'published'),
('elassoma-evergladei','Everglades Cüce Güneş Balığı','Elassoma evergladei','diger-baliklar','fish','Orta','Barışçıl, utangaç','Yalnızca 3 cm''lik, erkekleri üreme döneminde kadife siyahına ve parlak maviye bürünen küçük bir Kuzey Amerika balığı. Isıtıcısız tanklar için idealdir.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "12–26 °C (16–24 ideal)"], ["pH", "6.5–7.5"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl, utangaç"], ["Beslenme", "Etçil: canlı ve donuk küçük yem"], ["Üreme", "Yumurtlayan (bitkilere)"], ["Köken", "ABD güneydoğusu (Florida, Georgia, Karolinalar)"], ["Ömür", "2–3 yıl"], ["Özellikler", "Isıtıcısız tank, kış dinlenmesi"]]'::jsonb,array['cüce güneş balığı','pygmy sunfish','everglades pygmy sunfish','elassoma','elassoma evergladei']::text[],false,'Kuru yemi nadiren yer. Kışın birkaç hafta serin tutulması (10–15 °C) üreme ve sağlık için iyidir.','[{"r": 500, "lat": 29, "lng": -82, "label": "Florida ve Georgia"}]'::jsonb,'published'),
('enneacanthus-chaetodon','Siyah Bantlı Güneş Balığı','Enneacanthus chaetodon','diger-baliklar','fish','Orta','Barışçıl','Gümüşi gövdesi üzerindeki keskin siyah bantlarla tanınan, asidik ve serin su seven bir güneş balığı. Sakin ve bitkili tanklarda iyi uyum sağlar.','[["Yetişkin boy", "8–10 cm"], ["Sıcaklık", "10–24 °C"], ["pH", "4.5–6.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl"], ["Beslenme", "Etçil: canlı ve donuk yem"], ["Üreme", "Yuva yapar, erkek bakar"], ["Köken", "ABD doğu kıyısı (New Jersey''den Florida''ya)"], ["Ömür", "5+ yıl"], ["Özellikler", "Asidik su, ısıtıcısız"]]'::jsonb,array['siyah bantlı güneş balığı','blackbanded sunfish','enneacanthus','enneacanthus chaetodon','güneş balığı']::text[],true,'Çok asidik ve yumuşak su ister; sert suda hastalanır.','[{"r": 600, "lat": 35, "lng": -77.5, "label": "ABD doğu kıyısı ovaları"}]'::jsonb,'published'),
('datnioides-microlepis','Siyam Kaplan Balığı','Datnioides microlepis','diger-baliklar','fish','Zor','Yırtıcı, sakin','Altın sarısı gövde üzerindeki dikey siyah bantlarıyla kaplana benzeyen iri bir yırtıcı. Sakin yüzer ama ağzına sığan balığı avlar.','[["Yetişkin boy", "40 cm (akvaryumda 30 cm)"], ["Sıcaklık", "24–28 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "500 L"], ["Huy", "Yırtıcı"], ["Beslenme", "Etçil: balık, karides, etsi yem"], ["Üreme", "Yumurtlayan (akvaryumda bilinmiyor)"], ["Köken", "Güneydoğu Asya (Mekong, Chao Phraya, Borneo, Sumatra)"], ["Ömür", "15+ yıl"], ["Özellikler", "Kaplan desenli yırtıcı"]]'::jsonb,array['siyam kaplan balığı','kaplan balığı','siamese tigerfish','datnoid','datnioides','datnioides microlepis']::text[],true,'Doğada nesli tehlikede; yalnızca kaynağı belli üretim bireyleri al. Ağzına sığan tüm balıkları yer.','[{"r": 700, "lat": 13, "lng": 102, "label": "Mekong ve Chao Phraya havzaları"}, {"r": 500, "lat": 0.5, "lng": 112, "label": "Borneo"}]'::jsonb,'published'),
('indostomus-paradoxus','Zırhlı Pipa Balığı (Indostomus)','Indostomus paradoxus','diger-baliklar','fish','Zor','Barışçıl, çok sakin','Yalnızca 3 cm''lik, iğne balığını andıran tuhaf görünümlü küçük bir balık. Çok yavaş hareket eder ve yalnızca canlı küçük yem yer; deneyimli nano tutkunları içindir.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "6.0–7.0"], ["Min. akvaryum", "20 L"], ["Huy", "Barışçıl, çok sakin"], ["Beslenme", "Etçil: canlı artemia, siklop"], ["Üreme", "Yumurtlayan, erkek bakar"], ["Köken", "Myanmar (Indawgyi Gölü)"], ["Ömür", "2–3 yıl"], ["Özellikler", "Nano, sıra dışı görünüm"]]'::jsonb,array['indostomus','indostomus paradoxus','armoured stickleback','zırhlı pipa balığı']::text[],true,'Hızlı balıklarla yem yarışını kaybeder; tek tür nano tankta tutulmalı.','[{"r": 80, "lat": 25.1, "lng": 96.3, "label": "Indawgyi Gölü"}]'::jsonb,'published'),
('nannostomus-beckfordi','Altın Kalem Balığı','Nannostomus beckfordi','characiformlar','fish','Kolay','Barışçıl','Gövde boyunca uzanan siyah-altın çizgisi ve erkeklerdeki kırmızı yüzgeç işaretleriyle zarif bir kalem balığı. Bitkili tankların sakin orta ve üst katlarında yaşar; geceleri deseni bantlı hâle döner.','[["Yetişkin boy", "4–5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "50 L"], ["Huy", "Barışçıl, 6+ grup"], ["Beslenme", "Omnivor: ince granül, küçük canlı yem"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Güney Amerika (Guyana, Surinam, Amazon''un kuzeyi)"], ["Ömür", "5 yıl"], ["Özellikler", "Gece deseni değişir"]]'::jsonb,array['altın kalem balığı','kalem balığı','golden pencilfish','pencilfish','nannostomus','nannostomus beckfordi']::text[],false,null,'[{"r": 600, "lat": 3, "lng": -57, "label": "Guyana ve Amazon''un kuzeyi"}]'::jsonb,'published'),
('nannostomus-marginatus','Cüce Kalem Balığı','Nannostomus marginatus','characiformlar','fish','Kolay','Barışçıl','Kalem balıklarının en küçüğü; üç siyah çizgisi ve kırmızı yüzgeç işaretleriyle nano tanklara çok yakışır.','[["Yetişkin boy", "2.5–3.5 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl, 8+ grup"], ["Beslenme", "Omnivor: küçük granül, artemia"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Güney Amerika (Kolombiya, Peru, Brezilya, Guyana, Surinam)"], ["Ömür", "3–5 yıl"], ["Özellikler", "Nano karakid"]]'::jsonb,array['cüce kalem balığı','dwarf pencilfish','kalem balığı','nannostomus marginatus','nannostomus']::text[],false,null,'[{"r": 900, "lat": 0, "lng": -60, "label": "Amazon havzası ve Guyana"}]'::jsonb,'published'),
('nannostomus-eques','Eğik Yüzen Kalem Balığı','Nannostomus eques','characiformlar','fish','Kolay','Barışçıl','Başı yukarıda, eğik bir açıyla yüzmesiyle tanınan kalem balığı. Yüzeye yakın durur ve yüzen bitkilerin altında kendini güvende hisseder.','[["Yetişkin boy", "4–5 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl, 6+ grup"], ["Beslenme", "Omnivor: yüzey yemleri, küçük canlı yem"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Amazon havzası (Brezilya, Kolombiya, Peru)"], ["Ömür", "5 yıl"], ["Özellikler", "Eğik yüzme"]]'::jsonb,array['eğik kalem balığı','hockeystick pencilfish','brown pencilfish','kalem balığı','nannostomus eques']::text[],false,null,'[{"r": 700, "lat": -3, "lng": -62, "label": "Orta Amazon"}]'::jsonb,'published'),
('carnegiella-strigata','Mermer Balta Balığı','Carnegiella strigata','characiformlar','fish','Orta','Barışçıl, ürkek','Balta biçimli gövdesi ve mermer deseniyle yüzeyin hemen altında yaşar. Göğüs yüzgeçlerini kanat gibi kullanarak sudan sıçrayabilir.','[["Yetişkin boy", "3.5 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "60 L (uzun tank)"], ["Huy", "Barışçıl, 6+ sürü"], ["Beslenme", "Etçil: yüzeyde böcek, artemia, flake"], ["Üreme", "Yumurta saçıcı (akvaryumda zor)"], ["Köken", "Amazon (Peru, Kolombiya, Brezilya) ve Guyana"], ["Ömür", "3–5 yıl"], ["Özellikler", "Yüzey balığı, sıçrar"]]'::jsonb,array['mermer balta balığı','balta balığı','marbled hatchetfish','hatchetfish','carnegiella','carnegiella strigata']::text[],false,'Çok iyi sıçrar; sıkı kapak şart.','[{"r": 900, "lat": -2, "lng": -65, "label": "Amazon havzası"}]'::jsonb,'published'),
('gasteropelecus-sternicla','Gümüş Balta Balığı','Gasteropelecus sternicla','characiformlar','fish','Kolay','Barışçıl','Derin, balta biçimli gümüşi gövdesiyle yüzeyde sürü hâlinde yaşar; balta balıklarının en dayanıklısıdır.','[["Yetişkin boy", "6 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl, 6+ sürü"], ["Beslenme", "Etçil ağırlıklı: yüzey yemleri, artemia"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Güney Amerika (Amazon, Guyana)"], ["Ömür", "5 yıl"], ["Özellikler", "Yüzey balığı, sıçrar"]]'::jsonb,array['gümüş balta balığı','balta balığı','silver hatchetfish','common hatchetfish','hatchetfish','gasteropelecus','gasteropelecus sternicla']::text[],false,'Çok iyi sıçrar; sıkı kapak şart.','[{"r": 900, "lat": 1, "lng": -58, "label": "Amazon havzası ve Guyana"}]'::jsonb,'published'),
('anostomus-anostomus','Çizgili Baş Aşağı Balığı','Anostomus anostomus','characiformlar','fish','Orta','Yarı agresif, tür içi','Başı aşağıda, eğik yüzerek kaya ve köklerdeki yosunu kemiren; kırmızı yüzgeçli, siyah-altın çizgili bir karakid.','[["Yetişkin boy", "12–18 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.8–7.5"], ["Min. akvaryum", "200 L"], ["Huy", "Tür içi agresif; tek ya da 6+ tutulmalı"], ["Beslenme", "Omnivor: yosun, bitkisel yem, küçük omurgasız"], ["Üreme", "Yumurta saçıcı (akvaryumda nadir)"], ["Köken", "Amazon ve Orinoco (Brezilya, Kolombiya, Venezuela, Guyana)"], ["Ömür", "5–10 yıl"], ["Özellikler", "Baş aşağı yüzme"]]'::jsonb,array['çizgili baş aşağı balığı','baş aşağı balığı','striped headstander','headstander','anostomus','anostomus anostomus']::text[],false,'Yumuşak yapraklı bitkileri yiyebilir. Sıçrayabilir, kapak şart.','[{"r": 800, "lat": 4, "lng": -62, "label": "Orinoco ve Guyana Kalkanı"}]'::jsonb,'published'),
('abramites-hypselonotus','Yüksek Sırtlı Baş Aşağı Balığı','Abramites hypselonotus','characiformlar','fish','Orta','Yarı agresif','Yüksek sırtı ve koyu bantlarıyla tanınan, baş aşağı eğik yüzen bir karakid. Gençken sakin, yaşlandıkça tür içinde huysuzlaşır.','[["Yetişkin boy", "12–14 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "200 L"], ["Huy", "Tür içi agresif; tek tutulması önerilir"], ["Beslenme", "Omnivor; bitkileri yer"], ["Üreme", "Yumurta saçıcı"], ["Köken", "Amazon, Orinoco ve Paraná havzaları"], ["Ömür", "5–10 yıl"], ["Özellikler", "Baş aşağı yüzme"]]'::jsonb,array['yüksek sırtlı baş aşağı balığı','marbled headstander','headstander','abramites','abramites hypselonotus']::text[],false,'Bitkili tanka uygun değildir; sıçrayabilir, kapak şart.','[{"r": 1100, "lat": -8, "lng": -60, "label": "Amazon ve Paraná havzaları"}]'::jsonb,'published'),
('distichodus-sexfasciatus','Altı Bantlı Distichodus','Distichodus sexfasciatus','characiformlar','fish','Zor','Yarı agresif, bitki yer','Gençken turuncu gövde üzerinde altı siyah bantla çok çekicidir; ancak çok büyür ve bitkileri yer. Yalnızca büyük tanklar içindir.','[["Yetişkin boy", "50+ cm (akvaryumda 30–40 cm)"], ["Sıcaklık", "22–26 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "750 L"], ["Huy", "Tür içi agresif"], ["Beslenme", "Otçul ağırlıklı: sebze, spirulina, pelet"], ["Üreme", "Yumurta saçıcı (akvaryumda bilinmiyor)"], ["Köken", "Orta Afrika (Kongo havzası, Tanganyika Gölü)"], ["Ömür", "10+ yıl"], ["Özellikler", "Büyük, otçul"]]'::jsonb,array['altı bantlı distichodus','six banded distichodus','distichodus','distichodus sexfasciatus']::text[],false,'Mağazalarda 5 cm''lik yavrular satılır ama çok büyür; bitkili tanka konmaz.','[{"r": 700, "lat": -3, "lng": 22, "label": "Kongo Havzası"}]'::jsonb,'published'),
('potamotrygon-motoro','Benekli Tatlı Su Vatozu (Motoro)','Potamotrygon motoro','ilkel-siradisi-baliklar','fish','Zor','Barışçıl; küçük dip balıklarını yer','Turuncu halkalı benekleriyle en bilinen tatlı su vatozu. Zamanla sahibini tanır ve elden yem alacak kadar evcilleşir; ama çok geniş bir taban alanı ve kusursuz su kalitesi ister.','[["Yetişkin boy", "Disk 35–45 cm (dişiler daha büyük)"], ["Sıcaklık", "24–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "1000 L, taban en az 2×1 m"], ["Huy", "Barışçıl; dip balıklarını avlar"], ["Beslenme", "Etçil: karides, midye, solucan, balık eti"], ["Üreme", "Canlı doğurur"], ["Köken", "Güney Amerika (Amazon, Orinoco, Paraná–Paraguay)"], ["Ömür", "15+ yıl"], ["Özellikler", "Zehirli kuyruk dikeni"]]'::jsonb,array['motoro','tatlı su vatozu','vatoz','freshwater stingray','stingray','potamotrygon','potamotrygon motoro']::text[],true,'Kuyruğundaki zehirli diken çok acı ve tehlikeli yaralara yol açar; tankta çalışırken dikkatli ol. Nitrata ve kötü su kalitesine çok hassastır; güçlü filtre ve sık su değişimi şart. Bazı ülkelerde bulundurulması izne tabidir.','[{"r": 900, "lat": -4, "lng": -60, "label": "Amazon Havzası"}, {"r": 600, "lat": -21, "lng": -58, "label": "Paraná–Paraguay havzası"}]'::jsonb,'published'),
('lepisosteus-oculatus','Benekli Gar Balığı (Spotted Gar)','Lepisosteus oculatus','ilkel-siradisi-baliklar','fish','Zor','Yırtıcı, sakin','Uzun gagası ve sert, elmas biçimli pullarıyla dinozor çağından kalma bir görünüme sahip Kuzey Amerika yırtıcısı. Yüzeyden hava alabilir.','[["Yetişkin boy", "60–90 cm (akvaryumda 60 cm)"], ["Sıcaklık", "18–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "750 L"], ["Huy", "Yırtıcı"], ["Beslenme", "Etçil: balık, karides, etsi pelet"], ["Üreme", "Yumurtlayan"], ["Köken", "ABD (Büyük Göller''den Meksika Körfezi''ne)"], ["Ömür", "15–20 yıl"], ["Özellikler", "İlkel, hava solur"]]'::jsonb,array['benekli gar','spotted gar','gar','gar balığı','lepisosteus','lepisosteus oculatus']::text[],false,'Yumurtaları zehirlidir. Ağzına sığan tüm balıkları yer; kapak şart.','[{"r": 900, "lat": 34, "lng": -91, "label": "Mississippi havzası ve Körfez kıyısı"}]'::jsonb,'published')
